package patterns2;

public class OddNumbSquare {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i=1;i<=5;i++) {
			for(int j=1;j<10;j=j+2) {
				System.out.print(j+" ");
			}
			System.out.println();
		}

	}

}


//1 3 5 7 9
//1 3 5 7 9
//1 3 5 7 9
//1 3 5 7 9
//1 3 5 7 9